      long ticks = (nanos >>> SHIFT[i]);

      long spanMask = SPANS[i] - 1;
      int mask = timerWheel.length - 1;
      int start = (int) (ticks & mask);
      int end = start + timerWheel.length;
      for (int j = start; j < end; j++) {
