    Node<K, V> node = data.get(nodeFactory.newLookupKey(key));
    if (node != null) {
      long now = expirationTicker().read();
      boolean expired = hasExpired(node, now);
      V value = node.getValue();
      if ((value != null) && (!expired || isComputingAsync(value))) {
