      drainKeyReferences();
      drainValueReferences();

      long now = expirationTicker().read();
      expireEntries(now);
      evictEntries(now);

      climb();
    } finally {
      if ((drainStatusOpaque() != PROCESSING_TO_IDLE)
          || !casDrainStatus(PROCESSING_TO_IDLE, IDLE)) {
        setDrainStatusOpaque(REQUIRED);
      }
    }
