  default void notifyOnReplace(K key, @Nullable V oldValue, @NonNull V newValue);
  default <T extends @Nullable Object, R extends @Nullable Object> Function<? super T, ? extends @Nullable R> statsAware( Function<? super T, ? extends @Nullable R> mappingFunction, boolean recordLoad);
  default <T extends @Nullable Object, U extends @Nullable Object, R extends @Nullable Object> BiFunction<? super T, ? super U, ? extends @Nullable R> statsAware( BiFunction<? super T, ? super U, ? extends R> remappingFunction);
  default <T extends @Nullable Object, U extends @Nullable Object, R extends @Nullable Object> BiFunction<? super T, ? super U, ? extends @Nullable R> statsAware( BiFunction<? super T, ? super U, ? extends @Nullable R> remappingFunction, boolean recordLoad);
